window.ADINKRA_SYMBOLS=[{"no":1,"name":"Gye Nyame","meaning":"Except God. A symbol expressing the omnipotence of God. Probably the most popular Adinkra symbol in Ghana.","img":"data:image/png;base64,"},{"no":2,"name":"Sankofa","meaning":"Go back and get it! A symbol of the wisdom of learning from the past to build for the future. From the Akan proverb, \"Se wo were fi na wosan kofa a yenkyiri,\" meaning, \"It is not taboo to go back for what you forgot (or left behind).\"","img":"data:image/png;base64,"},{"no":3,"name":"Sankofa","meaning":"Another Sankofa symbol.","img":"data:image/png;base64,"},{"no":4,"name":"Funtumfunefu","meaning":"Conjoined crocodiles. A symbol of unity in diversity giving a common destiny; sharing; from the proverb, \"Funtumfrafu...\"","img":"data:image/png;base64,"},{"no":5,"name":"Dwennimmen","meaning":"Ram's horns. A Symbol of Strength (In Mind, Body, and Soul), Humility, Wisdom, and Learning.","img":"assets/adinkra-images/masks/adinkra-5.png"},{"no":7,"name":"Nkyinkyim","meaning":"Twisting. A symbol representing the tortuous nature of life's journey and, also, the toughness, versatility, and dynamism required to thrive in it. Willis notes that it is also a symbol of dedication to service.","img":"assets/adinkra-images/masks/adinkra-7.png"},{"no":8,"name":"Odo Nnyew Fie Kwan (Odo Nyera Fie Kwan)","meaning":"Love does not lose its way home. Those led by love always end up in the right place.","img":"assets/adinkra-images/masks/adinkra-8.png"},{"no":9,"name":"Denkyem","meaning":"Crocodile. A symbol of adaptability and cleverness.","img":"assets/adinkra-images/masks/adinkra-9.png"},{"no":10,"name":"Nea Onnim","meaning":"He who does not know; from the proverb, \"When he who does not know learns, he gets to know.\" It is a symbol of knowledge, life-long education, and continued quest for knowledge.","img":"assets/adinkra-images/masks/adinkra-10.png"},{"no":11,"name":"Nsoromma","meaning":"Star (literally, \"child of the heavens\"). A symbol of faith and the belief in patronage and dependency on a supreme being.","img":"assets/adinkra-images/masks/adinkra-11.png"},{"no":12,"name":"Aban","meaning":"Fortress (or castle). A symbol of strength, seat of power, authority, and magnificence.","img":"data:image/png;base64,"},{"no":13,"name":"Abode Santann","meaning":"No meaning was provided for this symbol in the source document.","img":"assets/adinkra-images/masks/adinkra-13.png"},{"no":15,"name":"Abusua Pa","meaning":"Good family. A symbol of family unity, kinship ties, and family support. From the expression, \"Abusua pa mu na adoye ne koroye wo,\" to wit, \"It is in a good family that we have love and unity.\"","img":"data:image/png;base64,"},{"no":16,"name":"Adwo","meaning":"Calmness. A symbol for peace, tranquility, and quiet.","img":"data:image/png;base64,"},{"no":17,"name":"Agyin Dawuru","meaning":"Agyin's gong. A symbol of faithfulness, alertness, and dutifulness. Designed to commemorate the faithfulness of one Agyin who was a dutiful servant and gong-beater of the Asantehene.","img":"data:image/png;base64,"},{"no":18,"name":"Akoben","meaning":"War horn. A symbol of a call to action, readiness to be called to action, readiness, and voluntarism.","img":"assets/adinkra-images/masks/adinkra-18.png"},{"no":19,"name":"Akofena","meaning":"A sword of war (or the state ceremonial swords). A symbol of state authority, legality, the legitimized authority of a ruler, recognition of gallantry of heroic deeds. Ghana's coat of arms shows one of these ceremonial swords crossed with a linguist's staff in its top left quadrant.","img":"assets/adinkra-images/masks/adinkra-19.png"},{"no":20,"name":"Akoko Nan","meaning":"The foot of a hen. A symbol for discipline coupled with care and nurturing; from the Akan proverb, \"Akoko nan tia ba na enkum ba,\" literally, \"The foot of a hen steps on the child (chick) but it doesn't kill the child (chick).\"","img":"data:image/png;base64,"},{"no":21,"name":"Akoma Ntoaso","meaning":"Joining of hearts. A symbol of agreement, togetherness and unity or a charter. An amplification of the concept of Akoma.","img":"assets/adinkra-images/masks/adinkra-21.png"},{"no":22,"name":"Akoma","meaning":"Heart. A symbol of love, goodwill, patience, faithfulness, fondness, endurance, and consistency.","img":"assets/adinkra-images/masks/adinkra-22.png"},{"no":23,"name":"Ananse Ntentan (Ananse Ntontan)","meaning":"Spider's web. A symbol of wisdom, craftiness, creativity, and the complexities of life. It is the web of Ananse, the crafty spider who is preeminent in African folklore.","img":"assets/adinkra-images/masks/adinkra-23.png"},{"no":24,"name":"Ani Bere A Enso Gya","meaning":"No matter how red-eyed one becomes (i.e. how serious one becomes), his eyes do not spark flames. A symbol of patience, self-containment, self-discipline, and self-control.","img":"data:image/png;base64,"},{"no":25,"name":"Anyi Me Aye A","meaning":"If you will not praise me. A symbol of ingratitude, ungratefulness, and boorishness. From the expression, \"Anyi me aye a, nsee me din,\" to wit, \"If you will not praise me, don't spoil my name (that is, undermine my integrity).\"","img":"data:image/png;base64,"},{"no":26,"name":"Asaawa","meaning":"Sweet berry or miracle berry. A symbol of sweetness, sweet taste, pleasure, and hedonism. From the proverb, \"Asaawa se: Ode nka anomu,\" to wit, \"Sweetness does not stay in the mouth forever.\"","img":"data:image/png;base64,"},{"no":27,"name":"Asase Ye Duru","meaning":"The earth has weight. A symbol of providence and the divinity of Mother Earth.","img":"assets/adinkra-images/masks/adinkra-27.png"},{"no":28,"name":"Asetena Pa","meaning":"Good living. A symbol of conspicuous spending, indulgence, wealth, and upper social class. From the saying \"Asetena pa ye awerefire,\" to wit, \"Good living is forgetfulness (that is, good living makes one forget his humble beginnings)\"","img":"assets/adinkra-images/masks/adinkra-28.png"},{"no":29,"name":"Aya","meaning":"Fern. A symbol of endurance, independence, defiance against difficulties, hardiness, perseverance, and resourcefulness.","img":"assets/adinkra-images/masks/adinkra-29.png"},{"no":30,"name":"Bese Saka","meaning":"Bunch of cola nuts. A symbol of affluence, power, abundance, and plenty. Also a symbol of togetherness and unity.","img":"assets/adinkra-images/masks/adinkra-30.png"},{"no":31,"name":"Bi Nka Bi","meaning":"Fern. A symbol of endurance, independence, defiance against difficulties, hardiness, perseverance, and resourcefulness.","img":"assets/adinkra-images/masks/adinkra-31.png"},{"no":32,"name":"Boa Me Na Me Mmoa Wo","meaning":"Help me and let me help you. A symbol of cooperation and interdependence. From the aphorism, \"Boa me na me mmoa wo,\" to wit \"Help me and let me help you\" or, \"Benkum dware nifa na nifa nso adware benkum,\" to wit, \"The left (hand) washes the right and the right washes the left.\"","img":"assets/adinkra-images/masks/adinkra-32.png"},{"no":33,"name":"Boafo Ye Na","meaning":"The rarity of a willing helper. It is a symbol of support, patronage, cooperation, and teamwork. \"Boafo ye na,\" the popular Akan expression associated with this symbol, literally means \"Helpers are rare\" or \"Helpful people are rare.\"","img":"assets/adinkra-images/masks/adinkra-33.png"},{"no":34,"name":"Dame Dame","meaning":"Checkered. A symbol of craftiness, intelligence, and strategy.","img":"assets/adinkra-images/masks/adinkra-34.png"},{"no":35,"name":"Dono Ntoaso","meaning":"The double dono; joined tension talking drum. A symbol of united action, alertness, goodwill, praise, rejoicing, and adroitness.","img":"data:image/png;base64,"},{"no":36,"name":"Dono","meaning":"The tension talking drum. A symbol of appellation, praise, goodwill and rhythm.","img":"assets/adinkra-images/masks/adinkra-36.png"},{"no":37,"name":"Duafe","meaning":"Wooden comb. A symbol of feminine consideration or good feminine qualities such as patience, prudence, fondness, love, and care.","img":"assets/adinkra-images/masks/adinkra-37.png"},{"no":38,"name":"Dwantire","meaning":"Ram's head. A symbol of innocence and guiltlessness. From the proverb, \"Dwantire se: Me tiri mu faa; okwasea bobonya menni fo nti na mabo hyire,\" to wit, \"The head of the ram says: My conscience is free; the righteous fool who never tastes of guilt should not be dressed in black, hence, I am always in white.\" The idea here is that the guiltless fears no accusation.","img":"data:image/png;base64,"},{"no":39,"name":"Eban","meaning":"Fence. A symbol of safety, security, and love.","img":"assets/adinkra-images/masks/adinkra-39.png"},{"no":40,"name":"Epa","meaning":"Handcuffs. A symbol of law and justice.","img":"data:image/png;base64,"},{"no":41,"name":"Ese ne Tekrema","meaning":"Teeth and tongue. A symbol of improvement, advancement, growth, the need for friendliness and interdependence.","img":"assets/adinkra-images/masks/adinkra-41.png"},{"no":42,"name":"Esono Anantam","meaning":"Elephant's footprint. A symbol of leadership, protection, power, and security. From the aphorism, \"Wodi esono akyi a, hasuo nka wo,\" to wit, \"When you follow the elephant, you are not touched by (you don't get wet from) the dew on bushes.\"","img":"data:image/png;base64,"},{"no":43,"name":"Fafanto","meaning":"Butterfly. A symbol of tenderness, gentleness, honesty, and fragility.","img":"assets/adinkra-images/masks/adinkra-43.png"},{"no":44,"name":"Fawohodie","meaning":"Freedom or independence. A symbol of freedom, independence, emancipation, self-determination, and self-government. From the proverb, \"Fawohodie ne obre na enam,\" literally, \"Freedom walks with suffering,\" that is, \"Freedom or independence comes with responsibilities.\"","img":"assets/adinkra-images/masks/adinkra-44.png"},{"no":45,"name":"Fihankra","meaning":"An enclosed or secured compound house. A symbol of brotherhood, safety, security, completeness, and solidarity.","img":"assets/adinkra-images/masks/adinkra-45.png"},{"no":46,"name":"Fofo","meaning":"A flowering plant (bidens pilosa). A symbol of warning against jealousy and covetousness.","img":"data:image/png;base64,"},{"no":47,"name":"Gyawu Atiko","meaning":"The back of Gyawu's head. A symbol of valor and bravery. Used interchangeably with the Kwatakye Atiko symbol.","img":"assets/adinkra-images/masks/adinkra-47.png"},{"no":48,"name":"Hwehwemudua","meaning":"Measuring rod (rod of investigation) or rule. A symbol of excellence, superior quality, perfection, knowledge, and critical examination.","img":"data:image/png;base64,"},{"no":49,"name":"Hye Wo Nhye (Hye Anhye)","meaning":"Burn you won't burn (fig. unburnable). A symbol of toughness and imperishability; also a symbol of permanence.","img":"assets/adinkra-images/masks/adinkra-49.png"},{"no":50,"name":"Kete Pa","meaning":"Good bed. A symbol of good marriage, successful marriage, and good care. From the expression, \"Obaa ko aware pa a na yede no to kete pa so,\" to wit, \"It is when a woman enters a good marriage that she is put on a good bed.\"","img":"data:image/png;base64,"},{"no":51,"name":"Kokuromotie","meaning":"Thumb. A symbol of cooperation, participation, teamwork, indispensability, and harmony. From the proverb, \"Yensiane kokuromotie ho mmo po,\" to wit, \"We don't bypass the thumb to tie a knot.\" Anybody who tries the exercise of tying a knot without his thumbs quickly appreciates this proverb.","img":"data:image/png;base64,"},{"no":52,"name":"Kramo Bone Amma Yeanhu Kramo Pa","meaning":"The bad Muslim makes it difficult for a good one to be recognized. A symbol of warning against deception and hypocrisy.","img":"data:image/png;base64,"},{"no":53,"name":"Krapa (Musuyidee)","meaning":"Krapa means \"good soul\" while Musuyidee means \"a thing for removing filth or evil.\" It is a symbol of spiritual balance, good fortune, good luck, sanctity, spiritual strength, and the uprightness of spirit.","img":"assets/adinkra-images/masks/adinkra-53.png"},{"no":54,"name":"Kuronti ne Akwamu","meaning":"Kuronti and Akwamu. A symbol of democracy, sharing ideas, taking council.","img":"data:image/png;base64,"},{"no":55,"name":"Kwatakye Atiko","meaning":"The back of Kwatakye's head. A symbol of valor and bravery. This symbol is also called Gyawu Atiko. It is said to be a hairstyle of Kwatakye, a war captain of old Asante.","img":"assets/adinkra-images/masks/adinkra-55.png"},{"no":56,"name":"Kyemfere","meaning":"Potsherd. A symbol of knowledge, experience, service, keepsake, antiquity, rarity, and heirloom. From the proverb, \"Kyemfere se odaa ho akye, na onipa a onwenee no nso nye den?\" to wit, \"The potsherd claims it is old; what about the potter who molded it?\"","img":"data:image/png;base64,"},{"no":57,"name":"Mako","meaning":"Peppers. A symbol of inequality and uneven development; from the proverb \"All peppers on the same plant don't ripen at the same time.\"","img":"data:image/png;base64,"},{"no":58,"name":"Mate Masie","meaning":"I have heard and kept it. A symbol of wisdom, knowledge, and prudence. From the saying, \"Nyansa bon mu ne mate masie,\" to wit, \"The hole of wisdom is 'I have heard and kept it'\"","img":"assets/adinkra-images/masks/adinkra-58.png"},{"no":59,"name":"Mekyea Wo","meaning":"I greet you. A symbol of greetings, recognition, and respect. When two Akans meet, they first greet each other before proceeding to do anything else. They greet not just to exchange pleasantries but because to greet is to recognize a fellow human being.","img":"assets/adinkra-images/masks/adinkra-59.png"},{"no":60,"name":"Menso Wo Kenten","meaning":"I am not carrying your basket. A symbol of industry, self-reliance, and economic self-determination.","img":"data:image/png;base64,"},{"no":61,"name":"Mframadan","meaning":"Well-ventilated house. A symbol of resilience and readiness to face the vicissitudes of life.","img":"data:image/png;base64,"},{"no":62,"name":"Mmeramubere","meaning":"Female cross. Symbol of warmth, sunshine, and vitality.","img":"data:image/png;base64,"},{"no":63,"name":"Mmeramutene","meaning":"Male cross. A symbol of sunlight, warmth, endurance, and uprightness.","img":"data:image/png;base64,"},{"no":64,"name":"Mmere Dane","meaning":"Time changes (times change). A symbol of the temporariness of good times.","img":"data:image/png;base64,"},{"no":65,"name":"Mpatapo","meaning":"Pacification knot. A symbol of pacification, forgiveness, and reconciliation.","img":"assets/adinkra-images/masks/adinkra-65.png"},{"no":66,"name":"Mpuannum","meaning":"Five tufts (of hair). A symbol of loyalty and priestly office.","img":"assets/adinkra-images/masks/adinkra-66.png"},{"no":67,"name":"Nea Ope Se Obedi Hene","meaning":"He who wants to be a king. A symbol of the qualities of a leader, service, and leadership skills. From the expression, \"Nea ope se obedi hene daakye no firi asee sua som ansa,\" to wit, \"He who wants to be a king in the future begins by learning how to serve.\"","img":"data:image/png;base64,"},{"no":68,"name":"Nkonsonkonson","meaning":"Chain. A symbol of unity, community.","img":"assets/adinkra-images/masks/adinkra-68.png"},{"no":69,"name":"Nkotimsefo Mpua","meaning":"The hairstyle of court attendants. A symbol of loyalty and a readiness to serve.","img":"assets/adinkra-images/masks/adinkra-69.png"},{"no":70,"name":"Nkrabea","meaning":"Destiny. A symbol of destiny, determinism, unequal distribution of talents, and inequality. From the aphorism, \"Esono onipa biara ne ne nkrabea,\" or, \"Onyame nkrabea mu nni kwatibea\" which translate literally to \"Everybody has their own distinct destiny\" and \"God's destiny cannot be circumvented\" respectively.","img":"assets/adinkra-images/masks/adinkra-70.png"},{"no":71,"name":"Nkyemu (Nkyimu)","meaning":"The crossed divisions made on Adinkra cloth before the stamping of the symbols is done. A symbol of adroitness, precision, and quality craftsmanship.","img":"data:image/png;base64,"},{"no":72,"name":"Nnamfo Pa Baanu","meaning":"Two good friends. A symbol of friendship, fellowship, and comradeship. From the aphorism, \"Hu m'ani so ma me nti na atwe mmienu nam,\" (literally, \"It is because of 'blow the dust off my eyes' that two deer walk together\") or \"Adwen yedwen no baanu\" (literally, \"Thinking is done in pairs\"). Also, \"Ayonkofoo baanu goro obaa koro ho a, ntotoee ba\" (literally, \"When two friends play with one woman, it brings misunderstanding\").","img":"assets/adinkra-images/masks/adinkra-72.png"},{"no":73,"name":"Nsaa","meaning":"A type of woven cloth, renowned for its quality. A symbol of excellence, genuineness, and authenticity.","img":"assets/adinkra-images/masks/adinkra-73.png"},{"no":74,"name":"Nserewa","meaning":"Cowries. A symbol of affluence and wealth. Also a symbol of sacredness when used by priests. Cowries were traditionally used as money in parts of West Africa before the colonial era. In fact, the anglicized form of the Twi word for 'cowry'--'sedee'--is what was adopted as the name for the national currency when the nation weaned itself off of the Ghanaian pound after independence.","img":"data:image/png;base64,"},{"no":75,"name":"Nteasee","meaning":"Understanding. A symbol for understanding and cooperation.","img":"assets/adinkra-images/masks/adinkra-75.png"},{"no":76,"name":"Nyame Baatanpa (Awurade Baatanfo)","meaning":"God the good parent. A symbol of the caring and nurturing of God over all his creation.","img":"data:image/png;base64,"},{"no":77,"name":"Nyame Biribi Wo Soro","meaning":"God, there is something in the heavens. From the saying, \"God, there is something up there (in the heavens); let it come to me.\" A symbol of hope and inspiration.","img":"assets/adinkra-images/masks/adinkra-77.png"},{"no":78,"name":"Nyame Dua","meaning":"God's tree (sacred stump). A symbol of God's presence and protection.","img":"assets/adinkra-images/masks/adinkra-78.png"},{"no":79,"name":"Nyame Nti","meaning":"By God's grace. More literally, \"Because of God.\" A symbol of faith and trust in God. The proverb associated with this symbol is, \"Nyame nti, menwe wura,\" to wit, \"Because of God (by God's grace), I won't feed on leaves (like an animal).\"","img":"data:image/png;base64,"},{"no":80,"name":"Nyame Nwu Na Mawu","meaning":"God won't die for me to die; a symbol expressing the immortality of the human soul.","img":"assets/adinkra-images/masks/adinkra-80.png"},{"no":81,"name":"Nyansapo","meaning":"Wisdom knot. A symbol of wisdom, ingenuity, intelligence, and patience. The proverb associated with this Adinkra is \"Nyansapo wosane no badwenma,\" to wit, \"A wisdom knot is untied (only) by the wise.\" The Kwame Nkrumah University of Science and Technology (KNUST) uses Nyansapo in their logo and uses the associated proverb as their motto.","img":"assets/adinkra-images/masks/adinkra-81.png"},{"no":82,"name":"Obohemaa","meaning":"Diamond. Obohemaa literally means \"queen of stones\" and in this case represents a diamond. It is a symbol of preciousness, gem, and treasure. From the maxim, \"Wo de wo sika to aboo a, wowe,\" to wit, \"If you use your money to buy (non-precious) stones, you eat them.\"","img":"assets/adinkra-images/masks/adinkra-82.png"},{"no":83,"name":"Ohene Aniwa","meaning":"The king's eyes. A symbol of vigilance, far-sightedness, intelligence, protection, security, defence, authority, and power. From the aphorism, \"Ohene aniwa twa ne ho hyia,\" to wit, \"The king's eyes surround him,\" that is, \"The king sees everything.\"","img":"data:image/png;base64,"},{"no":84,"name":"Okodee Mmowere","meaning":"The talons of an eagle. A symbol of strength, bravery, and power. These attributes are derived from the character and traits of the eagle.","img":"assets/adinkra-images/masks/adinkra-84.png"},{"no":85,"name":"Okuafo Pa","meaning":"Good farmer. A symbol of diligence, hard work, and entrepreneurship.","img":"data:image/png;base64,"},{"no":86,"name":"Osram ne Nsoromma","meaning":"Moon and star. A symbol of faithfulness, fondness, harmony, benevolence, love, loyalty, and femininity.","img":"assets/adinkra-images/masks/adinkra-86.png"},{"no":87,"name":"Owo Foro Adobe","meaning":"A snake climbs a raffia palm. A symbol of ingenuity, excellence, feat performance, and performing the unusual or impossible.","img":"data:image/png;base64,"},{"no":88,"name":"Owuo Atwedee","meaning":"Ladder of death. A symbol of the certainty and universality of death.","img":"assets/adinkra-images/masks/adinkra-88.png"},{"no":89,"name":"Pempamsie","meaning":"Sew in readiness. A symbol of foresight, readiness, steadfastness, hardiness, valor, and fearlessness.","img":"assets/adinkra-images/masks/adinkra-89.png"},{"no":90,"name":"Sepow","meaning":"Executioner's knife. A symbol of justice.","img":"assets/adinkra-images/masks/adinkra-90.png"},{"no":91,"name":"Som Onyankopon","meaning":"Worship God. A symbol of devotion and worship. From the expression, \"Som Onyankopon\" which literally means, \"Worship God.\"","img":"data:image/png;base64,"},{"no":92,"name":"Sunsum (Ntoro)","meaning":"Soul. A symbol of spiritual purity and cleanliness of the soul. The Akans believe that this is the part of God the creator that is transmitted to a person through his father. A person's mother cannot transmit sunsum to him. Instead, she transfers her mogya (blood) to him.","img":"data:image/png;base64,"},{"no":93,"name":"Tabono","meaning":"Paddle or oar. A symbol of strength, confidence, and persistence. These attributes are derived from the qualities required of one who paddles a boat.","img":"data:image/png;base64,"},{"no":94,"name":"Tamfo Bebre","meaning":"The enemy will suffer; the enemy will stew in his own juice. A symbol for ill-will, jealousy, and envy.","img":"assets/adinkra-images/masks/adinkra-94.png"},{"no":95,"name":"UAC Nkanea","meaning":"UAC lights. A symbol of technological advancement.","img":"data:image/png;base64,"},{"no":96,"name":"Wawa Aba","meaning":"Seed of the wawa tree. A symbol of hardiness, toughness, and perseverance.","img":"data:image/png;base64,"},{"no":97,"name":"Wo Nsa Da Mu A","meaning":"When your hands are inside (the dish). A symbol of participatory government, democracy, and pluralism. From the aphorism, \"Wo nsa da mu a, wonni nnya wo,\" to wit, \"When your hands are inside the dish, people don't eat everything and leave you nothing.\"","img":"data:image/png;base64,"},{"no":98,"name":"Woforo Dua Pa A","meaning":"When you climb a good tree. A symbol of support for good causes.","img":"assets/adinkra-images/masks/adinkra-98.png"}];
